  wallet: {
    address: `0x${crypto.randomUUID().replaceAll("-", "").slice(0, 40)}`,
    balance: 25,
    escrow: 0,
    earned: 0,
  },
  reputation: 80,
  agent: {
    name: "research-node",
    skill: "项目尽调",
    runtime: "Ollama 本地模型",
    id: `agent_${crypto.randomUUID().slice(0, 8)}`,
  },
  task: null,
  step: 0,
};

const steps = [
  {
    title: "发布任务",
    body: "任务写入 Task API，预算准备进入 Base USDC 托管。",
    action: "发布任务并托管 USDC",
  },
