.task-form {
  display: grid;
  gap: 12px;
}

.task-form {
  grid-template-columns: 1fr 130px;
  align-items: end;
}

.wide {
  grid-column: 1 / -1;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 760;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  padding: 11px 12px;
  outline: none;
}

textarea {
  min-height: 116px;
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(18, 119, 103, 0.6);
  box-shadow: 0 0 0 3px rgba(18, 119, 103, 0.12);
}

.primary-button,
.ghost-button,
.step-button,
.wallet-button {
  min-height: 42px;
  padding: 0 14px;
  border-radius: var(--radius);
  cursor: pointer;
  font-weight: 850;
}

.primary-button {
  color: #fff;
  background: var(--accent);
}

.ghost-button {
  border: 1px solid var(--line);
  color: var(--ink);
  background: var(--surface-2);
}

.step-button {
  min-height: 34px;
  color: #fff;
  background: var(--blue);
}

.primary-button:hover,
.ghost-button:hover,
.step-button:hover {
  filter: brightness(0.97);
}

.info-card,
.task-card,
.step {
  border: 1px solid var(--line);
  background: var(--surface-2);
  padding: 14px;
  border-radius: var(--radius);
}

.info-card {
  margin-top: 14px;
}

.info-card.compact {
  background: #fbfcfa;
}

.info-card strong,
.task-card strong,
.step strong {
  display: block;
  margin-bottom: 6px;
}

.info-card p,
.task-card p,
.step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
  font-size: 0.9rem;
}

.timeline {
  display: grid;
  gap: 12px;
  margin-top: 14px;
}

.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 20px 0 12px;
}

.section-title span {
  color: var(--muted);
  font-size: 0.86rem;
  font-weight: 800;
}

.task-list,
.active-task,
.watchlist {
  display: grid;
  gap: 12px;
}

.watchlist {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.watch-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfa;
  padding: 14px;
}

.watch-card header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.watch-card h3 {
  margin: 0;
  font-size: 1rem;
}

.watch-card p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.55;
}

.watch-tag {
  flex: 0 0 auto;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  padding: 0 8px;
  border-radius: 999px;
  color: var(--accent);
  background: rgba(18, 119, 103, 0.1);
  font-size: 0.72rem;
  font-weight: 900;
}

.watch-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.template-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.template-grid button {
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--accent);
  background: rgba(18, 119, 103, 0.08);
  cursor: pointer;
  font-weight: 850;
}

.task-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.status-badge {
  flex: 0 0 auto;
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  padding: 0 9px;
  border-radius: 999px;
  color: var(--blue);
  background: rgba(53, 111, 159, 0.1);
  font-size: 0.76rem;
  font-weight: 900;
}

.status-paid .status-badge {
  color: var(--ok);
  background: rgba(36, 160, 111, 0.12);
}

.status-submitted .status-badge,
.status-running .status-badge {
  color: var(--warn);
  background: rgba(212, 138, 39, 0.13);
}

.action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.step {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  gap: 12px;
  align-items: center;
}

.step-index {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: var(--radius);
  color: #fff;
  background: var(--accent);
  font-weight: 900;
}

.step.pending .step-index {
  background: #9ca8a3;
}

.step.done .step-index {
  background: var(--ok);
}

.step.active {
  border-color: rgba(53, 111, 159, 0.48);
  background: #f7fbff;
}

.pill-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.pill {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  min-height: 26px;
  padding: 0 9px;
  border-radius: 999px;
  color: var(--accent);
  background: rgba(18, 119, 103, 0.1);
  font-size: 0.76rem;
  font-weight: 850;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.metrics div {
  min-height: 86px;
  display: grid;
  align-content: center;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  padding: 12px;
  text-align: center;
}

.flow-progress {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-top: 16px;
}

.progress-segment {
  height: 6px;
  border-radius: 999px;
  background: #d7dfd8;
  overflow: hidden;
}

.progress-segment.active {
  background: linear-gradient(90deg, var(--accent), var(--blue));
}

.metrics span {
  display: block;
  color: var(--accent-2);
  font-size: 1.48rem;
  font-weight: 900;
}

.metrics p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.76rem;
}

.rules {
  margin: 10px 0 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.65;
  font-size: 0.88rem;
}

@media (max-width: 1080px) {
  .hero,
  .layout {
    grid-template-columns: 1fr;
  }

  .infra-strip {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 680px) {
  .app {
    padding: 16px;
  }

  .topnav {
    align-items: stretch;
    flex-direction: column;
  }

  .nav-tabs {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
  }

  .infra-strip,
  .task-form,
  .metrics,
  .template-grid,
  .watchlist {
    grid-template-columns: 1fr;
  }

  .step {
    grid-template-columns: 34px 1fr;
  }

  .step-button {
    grid-column: 1 / -1;
  }

  .wallet-card {
    grid-template-columns: 13px minmax(0, 1fr);
  }

  .wallet-button {
    grid-column: 1 / -1;
  }

  .task-card-head,
  .section-title {
    align-items: flex-start;
    flex-direction: column;
  }
}

