    radial-gradient(circle at 78% 22%, rgba(0, 113, 227, 0.16), transparent 28%),
    radial-gradient(circle at 18% 82%, rgba(134, 134, 139, 0.16), transparent 34%),
    #fff;
  box-shadow: var(--shadow);
}

.eyebrow,
.label {
  margin: 0 0 8px;
  color: var(--accent);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
