        : createEncoder({ contentTopic: WAKU_CONTENT_TOPIC });
    const handleWakuMessage = (wakuMessage) => {
      if (!wakuMessage.payload) return;
      try {
        const packet = JSON.parse(new TextDecoder().decode(wakuMessage.payload));
        if (!isOwnRecipient(packet.to)) return;
        state.messages.unshift({
          id: packet.id || `msg_in_${String(Date.now()).slice(-7)}`,
          from: packet.from,
          to: packet.to,
          route: "waku",
          direction: "inbound",
          body: packet.body,
          encrypted: packet.encrypted || `waku:${hashPayload(packet).slice(2)}`,
          timestamp: packet.timestamp || new Date().toLocaleString("en-US"),
        });
        saveState();
        render();
        showToast("Waku message received");
      } catch (error) {
        console.warn("Ignored malformed Waku message", error);
      }
    };
    let subscription = null;
    if (typeof node.filter.createSubscription === "function") {
      const result = await node.filter.createSubscription({ contentTopics: [WAKU_CONTENT_TOPIC] });
      subscription = result.subscription;
      await subscription.subscribe([decoder], handleWakuMessage);
    } else if (typeof node.filter.subscribe === "function") {
      subscription = await node.filter.subscribe([decoder], handleWakuMessage);
    } else {
      throw new Error("Waku Filter API is unavailable");
    }
    networkRuntime.wakuNode = node;
    networkRuntime.wakuEncoder = encoder;
    networkRuntime.wakuSubscription = subscription;
    updateNetworkStatus();
    showToast("Waku connected");
  } catch (error) {
    elements.wakuStatus.textContent = `Waku failed: ${error.message}`;
    showToast("Waku connection failed");
  }
}

function withTimeout(promise, timeoutMs, message) {
  return Promise.race([
    promise,
