async function connectXmtp() {
  if (networkRuntime.xmtpClient) return;
  elements.xmtpStatus.textContent = "Requesting wallet...";
  if (!hasInjectedWallet()) {
    elements.xmtpStatus.textContent = "XMTP failed: no browser wallet detected";
    showToast("Connect a browser wallet first");
    return;
  }
  elements.xmtpStatus.textContent = "Connecting XMTP...";
  try {
    const [account] = await window.ethereum.request({ method: "eth_requestAccounts" });
    if (!account) throw new Error("No wallet account selected");
    state.wallet.connectedAddress = account;
    state.wallet.chainId = await window.ethereum.request({ method: "eth_chainId" });
    state.wallet.mode = "connected";
    state.wallet.error = "";
    saveState();
    render();
    elements.xmtpStatus.textContent = "Wallet connected. Loading XMTP...";
    installWorkerProxy();
    const { Client, IdentifierKind } = await import("https://esm.sh/@xmtp/browser-sdk?bundle");
    const signer = {
      type: "EOA",
      getIdentifier: () => ({ identifier: account, identifierKind: IdentifierKind.Ethereum }),
      signMessage: async (message) => {
        const signature = await window.ethereum.request({ method: "personal_sign", params: [message, account] });
        return hexToBytes(signature);
