function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) return defaultState();
    const defaults = defaultState();
    return normalizeState({
      ...defaults,
      ...saved,
      wallet: { ...defaults.wallet, ...saved.wallet },
      agent: { ...defaults.agent, ...saved.agent },
      profile: { ...defaults.profile, ...saved.profile },
      relationships: saved.relationships || [],
      messages: saved.messages || [],
      selfTests: saved.selfTests || [],
      tasks: saved.tasks || [],
    });
  } catch {
    return defaultState();
  }
}

function normalizeState(nextState) {
  const validSkills = [
    "Investment opportunity analysis",
    "Token risk scan",
    "Yield opportunity scan",
    "Airdrop opportunity analysis",
  ];
  nextState.agent.skill = validSkills.includes(nextState.agent.skill)
    ? nextState.agent.skill
    : "Investment opportunity analysis";
  nextState.agent.runtime = "Online Agent API";
  nextState.agent.modelStatus = nextState.agent.modelStatus || "Not tested";
  nextState.profile.xmtp = nextState.profile.xmtp || nextState.wallet.connectedAddress || nextState.wallet.address;
  nextState.profile.messageEndpoint = nextState.profile.messageEndpoint || `xmtp:${nextState.profile.xmtp}`;
  nextState.profile.profileURI = nextState.profile.profileURI || `ipfs://${hashPayload(nextState.profile).slice(2)}.json`;
  nextState.relationships = nextState.relationships || [];
  nextState.messages = nextState.messages || [];
  nextState.selfTests = nextState.selfTests || [];
  nextState.wallet.error = ["missingWallet", "walletCancelled"].includes(nextState.wallet.error) ? nextState.wallet.error : "";
  return nextState;
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
