};

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) return defaultState();
    return {
      ...defaultState(),
      ...saved,
      wallet: { ...defaultState().wallet, ...saved.wallet },
      spend: { ...defaultState().spend, ...saved.spend },
      policy: { ...defaultState().policy, ...saved.policy },
      relationships: saved.relationships || [],
      messages: saved.messages || [],
      log: saved.log || [],
    };
  } catch {
    return defaultState();
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function showToast(message) {
  elements.toast.textContent = message;
  elements.toast.classList.add("visible");
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => elements.toast.classList.remove("visible"), 2200);
}

function shortAddress(address) {
  if (!address) return "Local Agent";
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function formatTime(timestamp) {
  const minutes = Math.max(1, Math.round((Date.now() - timestamp) / 60000));
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function getAgent(id) {
  return seedAgents.find((agent) => agent.id === id) || seedAgents[0];
}

function selectedAgent() {
  return getAgent(state.selectedAgentId);
}

function relationFor(agentId, relation) {
  return state.relationships.find((item) => item.agentId === agentId && item.relation === relation);
}

function relationshipsFor(agentId) {
  return state.relationships.filter((item) => item.agentId === agentId);
}

function addLog(title, detail) {
  state.log.unshift({
    id: `log_${crypto.randomUUID()}`,
    title,
    detail,
    createdAt: Date.now(),
  });
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

function filteredAgents() {
  const query = elements.agentSearch.value.trim().toLowerCase();
  return seedAgents.filter((agent) => {
    const matchesQuery = [agent.name, agent.handle, agent.description, ...agent.interests, ...agent.skills]
      .join(" ")
      .toLowerCase()
      .includes(query);
    const filter = state.agentFilter;
    const matchesFilter =
      filter === "all" ||
      (filter === "verified" && agent.verified) ||
      agent.category === filter ||
      agent.interests.some((interest) => interest.toLowerCase() === filter);
    return matchesQuery && matchesFilter;
  });
}

function setRelationship(agentId, relation) {
  const agent = getAgent(agentId);
  const existingIndex = state.relationships.findIndex((item) => item.agentId === agentId && item.relation === relation);
  if (existingIndex >= 0) {
    state.relationships.splice(existingIndex, 1);
    addLog(`${relationLabel(relation)} removed`, `Your Agent removed ${relationLabel(relation)} from ${agent.name}.`);
    showToast(`${relationLabel(relation)} removed`);
  } else {
    state.relationships = state.relationships.filter((item) => !(item.agentId === agentId && relation === "block"));
    state.relationships.unshift({
      agentId,
      relation,
      note: `${relationLabel(relation)} relationship created by your Agent.`,
      createdAt: Date.now(),
    });
    addLog(`${relationLabel(relation)} relationship created`, `${agent.name} was added to ${relationLabel(relation)} because it matches your social policy.`);
    showToast(`${relationLabel(relation)} ${agent.name}`);
  }
  state.selectedAgentId = agentId;
  saveState();
  render();
}

function relationLabel(relation) {
  return relation.charAt(0).toUpperCase() + relation.slice(1);
}

async function connectWallet() {
  const provider = window.ethereum?.providers?.find((item) => item.isMetaMask) || window.ethereum;
  if (!provider?.request) {
    showToast("No browser wallet detected");
    return;
  }
  try {
    const accounts = await provider.request({ method: "eth_requestAccounts" });
    const chainId = await provider.request({ method: "eth_chainId" });
    state.wallet.address = accounts[0] || "";
    state.wallet.chainId = chainId;
    state.wallet.connected = Boolean(accounts[0]);
    addLog("Wallet connected", `Wallet ${shortAddress(state.wallet.address)} connected for Agent social actions.`);
    saveState();
    render();
    showToast("Wallet connected");
  } catch (error) {
    showToast(error.message || "Wallet connection cancelled");
  }
}

function render() {
  renderShell();
  renderDiscover();
  renderContacts();
  renderMessages();
  renderLog();
  renderWallet();
  renderInspector();
}

function renderShell() {
