  elements.panels.forEach((panel) => panel.classList.toggle("active", panel.dataset.panel === state.view));
  const [title, subtitle] = viewCopy[state.view];
  elements.viewTitle.textContent = title;
  elements.viewSubtitle.textContent = subtitle;
  elements.contactBadge.textContent = state.relationships.length;
  elements.messageBadge.textContent = state.messages.filter((message) => message.direction === "inbound").length;
  elements.walletShort.textContent = shortAddress(state.wallet.address);
  elements.walletState.textContent = state.wallet.connected ? "Connected" : "Not connected";
}

function renderDiscover() {
