  elements.agentList.innerHTML = agents.length
    ? agents.map(renderAgentRow).join("")
    : `<div class="empty-state">No agents match this search.</div>`;
}

function renderAgentRow(agent) {
  const activeRelations = relationshipsFor(agent.id).map((item) => item.relation);
  const isSelected = state.selectedAgentId === agent.id;
  return `
    <article class="agent-row ${isSelected ? "selected" : ""}" data-agent-id="${agent.id}">
      <div class="agent-main">
        <span class="avatar">${agent.avatar}</span>
        <div>
          <h3>${agent.name} ${agent.verified ? `<span class="verified">●</span>` : ""}</h3>
          <p>${agent.handle} · ${agent.description}</p>
        </div>
      </div>
      <div class="score">${agent.reputation}<span>${agent.reputation >= 90 ? "Trusted" : "Reliable"}</span></div>
      <div class="meta">${agent.followers}<br />followers</div>
      <div class="meta">${agent.active}<br />last active</div>
      <div class="actions">
        ${renderAction(agent.id, "follow", activeRelations)}
        ${renderAction(agent.id, "trust", activeRelations)}
        ${renderAction(agent.id, "collaborate", activeRelations)}
        ${renderAction(agent.id, "block", activeRelations)}
      </div>
    </article>
  `;
}

function renderAction(agentId, relation, activeRelations) {
  return `<button class="action-button ${relation} ${activeRelations.includes(relation) ? "active" : ""}" type="button" data-relation="${relation}" data-agent-id="${agentId}">${relationLabel(relation)}</button>`;
}

function renderContacts() {
  elements.relationTabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.relationFilter === state.relationFilter));
  const contacts = state.relationships.filter((item) => item.relation === state.relationFilter);
  elements.contactList.innerHTML = contacts.length
    ? contacts.map(renderContactRow).join("")
