      <p class="meta">${item.note}</p>
      <button class="action-button follow" type="button" data-message-agent="${agent.id}">Message</button>
    </article>
  `;
}

function renderMessages() {
  const relatedAgentIds = [...new Set([...state.relationships.map((item) => item.agentId), ...state.messages.map((item) => item.agentId)])];
