  elements.conversationList.innerHTML = relatedAgentIds.map((agentId) => {
    const agent = getAgent(agentId);
    const lastMessage = [...state.messages].reverse().find((message) => message.agentId === agentId);
    return `
      <button class="conversation-button ${state.selectedAgentId === agentId ? "active" : ""}" type="button" data-conversation-agent="${agentId}">
