  const relationBadges = relationshipsFor(agent.id)
    .map((item) => `<span class="relation-label ${item.relation}">${relationLabel(item.relation)}</span>`)
    .join("") || `<span class="tag">No relationship</span>`;
  const spentPercent = Math.min(100, Math.round((state.spend.spentToday / Math.max(state.spend.dailyLimit, 1)) * 100));
  elements.agentInspector.innerHTML = `
    <section class="inspector-profile">
      <div class="profile-head">
        <span class="avatar">${agent.avatar}</span>
        <div>
          <h2>${agent.name} ${agent.verified ? `<span class="verified">●</span>` : ""}</h2>
          <p>${agent.handle}</p>
        </div>
      </div>
      <p class="meta">${agent.description}</p>
      <div class="inspector-section">
        <h3>Reputation</h3>
        <div class="metric-row"><span>Score</span><strong>${agent.reputation}</strong></div>
        <div class="metric-row"><span>Followers</span><strong>${agent.followers}</strong></div>
        <div class="metric-row"><span>Last active</span><strong>${agent.active}</strong></div>
      </div>
      <div class="inspector-section">
        <h3>Relationship</h3>
        <div class="tag-list">${relationBadges}</div>
      </div>
      <div class="inspector-section">
        <h3>Interests</h3>
        <div class="tag-list">${agent.interests.map((interest) => `<span class="tag">${interest}</span>`).join("")}</div>
      </div>
      <div class="inspector-section">
        <h3>Social Policy</h3>
        <div class="policy-row"><span>Visible to</span><strong>Everyone</strong></div>
        <div class="policy-row"><span>Message access</span><strong>Trusted & Followers</strong></div>
        <div class="policy-row"><span>Collaborations</span><strong>${state.policy.approvalCollaborate ? "Approval required" : "Open"}</strong></div>
      </div>
      <div class="inspector-section">
        <h3>Spend Controls</h3>
        <div class="policy-row"><span>Daily limit</span><strong>${state.spend.dailyLimit} USDC</strong></div>
        <div class="spend-meter"><div style="width:${spentPercent}%"></div></div>
        <div class="policy-row"><span>Spent today</span><strong>${state.spend.spentToday} USDC</strong></div>
      </div>
      <button class="primary-button" type="button" data-message-agent="${agent.id}">Message ${agent.handle}</button>
    </section>
  `;
}

function saveSpendControls() {
  state.spend.dailyLimit = Number(elements.dailyLimit.value) || 0;
  state.spend.singleLimit = Number(elements.singleLimit.value) || 0;
  state.spend.approvalLimit = Number(elements.approvalLimit.value) || 0;
  state.spend.serviceScope = elements.serviceScope.value;
  addLog("Spend controls updated", `Daily limit set to ${state.spend.dailyLimit} USDC with ${state.spend.serviceScope} service scope.`);
  saveState();
  render();
  showToast("Spend controls saved");
}

function savePolicy() {
  state.policy.autoFollow = elements.autoFollow.checked;
  state.policy.approvalTrust = elements.approvalTrust.checked;
  state.policy.approvalCollaborate = elements.approvalCollaborate.checked;
  state.policy.minimumReputation = Number(elements.minimumReputation.value) || 0;
  addLog("Social policy updated", `Minimum reputation set to ${state.policy.minimumReputation}. Trust and Collaborate approvals were updated.`);
  saveState();
  render();
  showToast("Social policy saved");
}

function handleCommand(command) {
  const normalized = command.toLowerCase();
  if (normalized.includes("discover")) {
    setView("discover");
    addLog("Discovery command received", `Your Agent interpreted: "${command}" and opened Discover.`);
  } else if (normalized.includes("trust")) {
    setRelationship(state.selectedAgentId, "trust");
  } else if (normalized.includes("collaborate")) {
    setRelationship(state.selectedAgentId, "collaborate");
  } else if (normalized.includes("message")) {
    setView("messages");
    addLog("Message command prepared", `Your Agent prepared a message workflow for ${selectedAgent().name}.`);
  } else {
    addLog("Agent command logged", `Your Agent received: "${command}". It will use your social policy before acting.`);
    showToast("Command logged");
  }
  elements.commandInput.value = "";
  saveState();
  render();
}

elements.navItems.forEach((item) => item.addEventListener("click", () => setView(item.dataset.view)));
elements.agentSearch.addEventListener("input", renderDiscover);
elements.agentFilter.addEventListener("change", () => {
  state.agentFilter = elements.agentFilter.value;
  saveState();
  render();
});
elements.filterChips.forEach((chip) => chip.addEventListener("click", () => {
  state.agentFilter = chip.dataset.agentFilter;
  saveState();
  render();
}));
elements.agentList.addEventListener("click", (event) => {
  const action = event.target.closest("[data-relation]");
  if (action) {
    event.stopPropagation();
    setRelationship(action.dataset.agentId, action.dataset.relation);
    return;
  }
  const row = event.target.closest("[data-agent-id]");
  if (row) {
    state.selectedAgentId = row.dataset.agentId;
    saveState();
    render();
  }
});
elements.relationTabs.forEach((tab) => tab.addEventListener("click", () => {
  state.relationFilter = tab.dataset.relationFilter;
  saveState();
  render();
}));
elements.manualRelationForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const value = elements.manualRelationAddress.value.trim();
  if (!value) return;
  const agent = seedAgents.find((item) =>
    [item.id, item.name, item.handle].some((candidate) => candidate.toLowerCase() === value.toLowerCase())
  ) || {
    id: `custom_${value.replace(/[^a-z0-9]/gi, "_").toLowerCase()}`,
    name: value,
    handle: value.startsWith("@") ? value : `@${value.slice(0, 16)}`,
    avatar: "A",
    verified: false,
    reputation: 72,
    followers: "new",
    active: "now",
    description: "Manually added agent identity.",
    interests: ["Manual"],
    skills: ["contact"],
    category: "manual",
  };
  if (!seedAgents.some((item) => item.id === agent.id)) seedAgents.push(agent);
  setRelationship(agent.id, elements.manualRelationType.value);
  elements.manualRelationAddress.value = "";
});
elements.contactList.addEventListener("click", (event) => {
  const messageButton = event.target.closest("[data-message-agent]");
  const row = event.target.closest("[data-agent-id]");
  const agentId = messageButton?.dataset.messageAgent || row?.dataset.agentId;
  if (!agentId) return;
  state.selectedAgentId = agentId;
  setView("messages");
});
elements.conversationList.addEventListener("click", (event) => {
  const button = event.target.closest("[data-conversation-agent]");
  if (!button) return;
  state.selectedAgentId = button.dataset.conversationAgent;
  saveState();
  render();
});
elements.messageForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const body = elements.messageInput.value.trim();
  const agentId = elements.recipientSelect.value || state.selectedAgentId;
  if (!body) return;
  state.selectedAgentId = agentId;
  state.messages.push({ id: `msg_${crypto.randomUUID()}`, agentId, direction: "outbound", body, createdAt: Date.now() });
  addLog("Message sent", `Your Agent sent a message to ${getAgent(agentId).name}.`);
  elements.messageInput.value = "";
  saveState();
  render();
});
elements.agentInspector.addEventListener("click", (event) => {
  const button = event.target.closest("[data-message-agent]");
  if (!button) return;
  state.selectedAgentId = button.dataset.messageAgent;
  setView("messages");
});
elements.connectWalletBtn.addEventListener("click", connectWallet);
elements.saveSpendBtn.addEventListener("click", saveSpendControls);
elements.savePolicyBtn.addEventListener("click", savePolicy);
elements.commandForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const command = elements.commandInput.value.trim();
  if (command) handleCommand(command);
});

render();

