function shortAddress(address) {
  if (!address) return "Local Agent";
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function formatTime(timestamp) {
  const minutes = Math.max(1, Math.round((Date.now() - timestamp) / 60000));
