async function sendCommandToLocalAgent(command) {
  if (!state.localAgent.connected || !state.localAgent.endpoint) return false;
  const payload = {
    command,
    selectedAgent: selectedAgent(),
    relationships: state.relationships,
    spend: state.spend,
    policy: state.policy,
  };
  const response = await fetchJsonWithTimeout(`${state.localAgent.endpoint}/action`, {
    method: "POST",
    timeoutMs: 10000,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const text = response.message || response.result || response.reply || "Local Agent completed the action.";
  addLog("Local Agent action", text);
  if (response.suggestedRelations?.length) {
    response.suggestedRelations.slice(0, 3).forEach((item) => {
      const agent = allAgents().find((candidate) => candidate.id === item.agentId || candidate.handle === item.agentId);
      if (agent && item.relation) {
        state.relationships.unshift({
          agentId: agent.id,
          relation: item.relation,
          note: item.reason || "Suggested by Local Agent.",
          createdAt: Date.now(),
        });
      }
    });
  }
  return true;
}

function render() {
  renderShell();
  renderDiscover();
  renderContacts();
  renderMessages();
  renderLog();
  renderWallet();

  const profile = state.localAgent.profile;
  const status = state.localAgent.status;
  const statusClass = status === "connected" ? "trust" : status === "found" || status === "detecting" || status === "connecting" ? "follow" : "block";
  const statusText = {
    connected: "Connected",
    found: "Found",
    detecting: "Detecting",
    connecting: "Connecting",
    offline: "Offline",
  }[status] || "Offline";
  elements.localAgentStatus.className = `relation-label ${statusClass}`;
  elements.localAgentStatus.textContent = statusText;
  elements.localAgentEndpoint.value = state.localAgent.endpoint || "";
  elements.connectLocalAgentBtn.disabled = status === "connecting" || status === "detecting";
  elements.detectLocalAgentBtn.disabled = status === "connecting" || status === "detecting";
  elements.disconnectLocalAgentBtn.disabled = !state.localAgent.connected;
  elements.localAgentProfile.innerHTML = profile
    ? `
      <span class="avatar small">${(profile.name || "L").slice(0, 1).toUpperCase()}</span>
      <div>
        <strong>${profile.name || "Local Agent"}</strong>
        <span>${profile.status || statusText} · ${(profile.skills || []).slice(0, 4).join(" · ") || "social · research · wallet-check"}</span>
      </div>
    `
    : `
      <span class="avatar small">L</span>
      <div>
        <strong>No local Agent connected</strong>
        <span>${state.localAgent.error || "Open your Agent app, then detect again."}</span>
      </div>
    `;
}

function renderInspector() {
  const agent = selectedAgent();
  const relationBadges = relationshipsFor(agent.id)
    .map((item) => `<span class="relation-label ${item.relation}">${relationLabel(item.relation)}</span>`)
    .join("") || `<span class="tag">No relationship</span>`;

