.capability-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.capability-list span {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0 10px;
  color: #343842;
  font-size: 13px;
}

.local-chat {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.96);
  overflow: hidden;
}

.local-chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.local-chat-header strong {
  font-size: 14px;
}

.local-chat-header .action-button {
  min-width: 62px;
  min-height: 32px;
}

.local-chat-list {
  display: flex;
  max-height: 220px;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  overflow: auto;
}

.local-chat-message {
  width: fit-content;
  max-width: 82%;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-soft);
  font-size: 13px;
  line-height: 1.45;
}

.local-chat-message.user {
  align-self: flex-end;
  border-color: #bdd4ff;
  background: var(--blue-soft);
}

.local-chat-message.agent {
  align-self: flex-start;
  background: #fff;
}

.local-chat-message small {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  font-size: 11px;
}

.settings-panel label {
  display: grid;
  gap: 7px;
  margin-bottom: 14px;
  color: #333740;
  font-size: 13px;
  font-weight: 650;
}

.toggle-row {
  grid-template-columns: 1fr auto;
  align-items: center;
}

.toggle-row input {
  width: 20px;
  min-height: 20px;
}

.composer-stack {
  position: absolute;
  right: 22px;
  bottom: 18px;
  left: 22px;
  display: grid;
  gap: 10px;
  z-index: 5;
}

.composer-stack .local-chat {
  margin: 0;
  box-shadow: 0 14px 38px rgba(21, 28, 41, 0.07);
  backdrop-filter: blur(16px);
}

.command-bar {
  position: static;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 10px;
  min-height: 64px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
}

.spark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid #cfe0ff;
  border-radius: 10px;
  background: var(--blue-soft);
  color: var(--blue);
}

.command-bar input {
  border-color: transparent;
  box-shadow: none;
}

