function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) {
      const nextState = defaultState();
      ensureNetworkBootstrap(nextState);
      purgeDemoAgents(nextState);
      applyLayoutMigration(nextState);
      return nextState;
    }
    const nextState = {
      ...defaultState(),
      ...saved,
      wallet: { ...defaultState().wallet, ...saved.wallet },
      localAgent: { ...defaultState().localAgent, ...saved.localAgent },
      onlineAgent: { ...defaultState().onlineAgent, ...saved.onlineAgent },
      spend: { ...defaultState().spend, ...saved.spend },
      policy: { ...defaultState().policy, ...saved.policy },
      network: {
        ...defaultState().network,
        ...saved.network,
        nostr: { ...defaultState().network.nostr, ...saved.network?.nostr },
        eventLog: saved.network?.eventLog || [],
      },
      customAgents: saved.customAgents || [],
      relationships: saved.relationships || [],
      messages: saved.messages || [],
      log: saved.log || [],
    };
    if (saved.contactsResetVersion !== CONTACTS_RESET_VERSION) {
      nextState.relationships = [];
      nextState.messages = [];
      nextState.customAgents = [];
      nextState.log = (nextState.log || []).filter((item) => item.title?.startsWith("Local Agent") || item.title?.includes("Local model"));
      nextState.contactsResetVersion = CONTACTS_RESET_VERSION;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(nextState));
    }
    ensureNetworkBootstrap(nextState);
    purgeDemoAgents(nextState);
    applyLayoutMigration(nextState);
    return nextState;
  } catch {
    const nextState = defaultState();
    ensureNetworkBootstrap(nextState);
    purgeDemoAgents(nextState);
    applyLayoutMigration(nextState);
    return nextState;
  }
}

