  if (!nostr.privateKeyHex) {
    const secretKey = tools.generateSecretKey();
    nostr.privateKeyHex = bytesToHex(secretKey);
    nostr.publicKey = tools.getPublicKey(secretKey);
  } else if (!nostr.publicKey) {
    nostr.publicKey = tools.getPublicKey(hexToBytes(nostr.privateKeyHex));
