function indexNetworkAgents() {
  const profiles = new Map();
  const heartbeats = new Map();
  const relations = new Map();

  validNetworkEvents().forEach((event) => {
    const payload = event.payload || {};
    if (event.type === "agent.profile") profiles.set(payload.agentId, { ...payload, actor: event.actor, cid: event.cid });
    if (event.type === "agent.heartbeat") heartbeats.set(payload.agentId, payload.lastSeen || event.timestamp);
    if (event.type.startsWith("relation.") && payload.target && payload.relation) {
