function createNetworkEvent(type, payload, actor = state?.network?.nodeId || "did:pkh:eip155:1:bootstrap") {
  const timestamp = Date.now();
  const body = {
    type,
    actor,
    payload,
    timestamp,
    topic: NETWORK_TOPIC,
  };
  const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(body)))).slice(0, 28);
  return {
    id: `evt_${crypto.randomUUID()}`,
    ...body,
    cid: `ipfs://bafy${encoded.toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 24)}`,
    signature: `sig:${actor}:${encoded}`,
  };
}

function createBootstrapEvent(type, agent, payload = {}) {
  return createNetworkEvent(type, {
    agentId: agent.id,
    ...payload,
  }, `did:pkh:eip155:1:${agent.id}`);
}

function isLegacyDemoAgentId(id) {
  return LEGACY_DEMO_AGENT_IDS.has(String(id || ""));
}

function isLegacyDemoEvent(event) {
  const payload = event?.payload || {};
  return (
    isLegacyDemoAgentId(payload.agentId) ||
    isLegacyDemoAgentId(payload.target) ||
    LEGACY_DEMO_AGENT_IDS.has(String(event?.actor || "").split(":").pop()) ||
    String(event?.actor || "").includes("peer-agent_")
  );
}

function ensureNetworkBootstrap(targetState) {
  if (targetState.network.bootstrapVersion === NETWORK_BOOTSTRAP_VERSION) return;
  targetState.network.eventLog = (targetState.network.eventLog || []).filter((event) => !isLegacyDemoEvent(event));
  targetState.network.bootstrapVersion = NETWORK_BOOTSTRAP_VERSION;
  targetState.network.syncedAt = Date.now();
}

function purgeDemoAgents(targetState) {
  if (targetState.demoPurgeVersion === DEMO_PURGE_VERSION) return;
  targetState.network.eventLog = (targetState.network.eventLog || []).filter((event) => !isLegacyDemoEvent(event));
  targetState.customAgents = (targetState.customAgents || []).filter((agent) => !isLegacyDemoAgentId(agent.id));
  targetState.relationships = (targetState.relationships || []).filter((item) => !isLegacyDemoAgentId(item.agentId));
  targetState.messages = (targetState.messages || []).filter((item) => !isLegacyDemoAgentId(item.agentId));
  if (isLegacyDemoAgentId(targetState.selectedAgentId)) targetState.selectedAgentId = "";
  targetState.demoPurgeVersion = DEMO_PURGE_VERSION;
}

function applyLayoutMigration(targetState) {
  if (targetState.layoutVersion === LAYOUT_VERSION) return;
  targetState.view = "status";
  targetState.layoutVersion = LAYOUT_VERSION;
}

